27	ClientConfigurationPerRequest ProxyResolverConfiguration::getConfiguration(const Aws::Http::HttpRequest &)
28	{
29	    LOG_DEBUG(&Poco::Logger::get("AWSClient"), "Obtain proxy using resolver: {}", endpoint.toString());
30	
31	    std::lock_guard lock(cache_mutex);
32	
33	    std::chrono::time_point<std::chrono::system_clock> now = std::chrono::system_clock::now();
34	
35	    if (cache_ttl.count() && cache_valid && now <= cache_timestamp + cache_ttl && now >= cache_timestamp)
36	    {
37	        LOG_DEBUG(&Poco::Logger::get("AWSClient"), "Use cached proxy: {}://{}:{}", Aws::Http::SchemeMapper::ToString(cached_config.proxy_scheme), cached_config.proxy_host, cached_config.proxy_port);
38	        return cached_config;
39	    }
40	
41	    /// 1 second is enough for now.
42	    /// TODO: Make timeouts configurable.
43	    ConnectionTimeouts timeouts(
44	        Poco::Timespan(1000000), /// Connection timeout.
45	        Poco::Timespan(1000000), /// Send timeout.
46	        Poco::Timespan(1000000)  /// Receive timeout.
47	    );
48	
49	    try
50	    {
51	        /// It should be just empty GET request.
52	        Poco::Net::HTTPRequest request(Poco::Net::HTTPRequest::HTTP_GET, endpoint.getPath(), Poco::Net::HTTPRequest::HTTP_1_1);
53	
54	        const auto & host = endpoint.getHost();
55	        auto resolved_hosts = DNSResolver::instance().resolveHostAll(host);
56	
57	        if (resolved_hosts.empty())
58	            throw Exception(ErrorCodes::BAD_ARGUMENTS, "Proxy resolver cannot resolve host {}", host);
59	
60	        HTTPSessionPtr session;
61	
62	        for (size_t i = 0; i < resolved_hosts.size(); ++i)
63	        {
64	            auto resolved_endpoint = endpoint;
65	            resolved_endpoint.setHost(resolved_hosts[i].toString());
66	            session = makeHTTPSession(resolved_endpoint, timeouts, false);
67	
68	            try
69	            {
70	                session->sendRequest(request);
71	            }
72	            catch (...)
73	            {
74	                if (i + 1 == resolved_hosts.size())
75	                    throw;
76	            }
77	        }
78	
79	        Poco::Net::HTTPResponse response;
80	        auto & response_body_stream = session->receiveResponse(response);
81	
82	        if (response.getStatus() != Poco::Net::HTTPResponse::HTTP_OK)
83	            throw Exception("Proxy resolver returned not OK status: " + response.getReason(), ErrorCodes::BAD_ARGUMENTS);
84	
85	        String proxy_host;
86	        /// Read proxy host as string from response body.
87	        Poco::StreamCopier::copyToString(response_body_stream, proxy_host);
88	
89	        LOG_DEBUG(&Poco::Logger::get("AWSClient"), "Use proxy: {}://{}:{}", proxy_scheme, proxy_host, proxy_port);
90	
91	        cached_config.proxy_scheme = Aws::Http::SchemeMapper::FromString(proxy_scheme.c_str());
92	        cached_config.proxy_host = proxy_host;
93	        cached_config.proxy_port = proxy_port;
94	        cache_timestamp = std::chrono::system_clock::now();
95	        cache_valid = true;
96	
97	        return cached_config;
98	    }
99	    catch (...)
100	    {
101	        tryLogCurrentException("AWSClient", "Failed to obtain proxy");
102	        /// Don't use proxy if it can't be obtained.
103	        ClientConfigurationPerRequest cfg;
104	        return cfg;
105	    }
106	}
