108	void ProxyResolverConfiguration::errorReport(const ClientConfigurationPerRequest & config)
109	{
110	    if (config.proxy_host.empty())
111	        return;
112	
113	    std::lock_guard lock(cache_mutex);
114	
115	    if (!cache_ttl.count() || !cache_valid)
116	        return;
117	
118	    if (std::tie(cached_config.proxy_scheme, cached_config.proxy_host, cached_config.proxy_port)
119	            != std::tie(config.proxy_scheme, config.proxy_host, config.proxy_port))
120	        return;
121	
122	    /// Invalidate cached proxy when got error with this proxy
123	    cache_valid = false;
124	}
125	
