88	template <template <typename, bool> class Function>
89	AggregateFunctionPtr createAggregateFunctionQuantile(
90	    const std::string & name, const DataTypes & argument_types, const Array & params, const Settings *)
91	{
92	    /// Second argument type check doesn't depend on the type of the first one.
93	    Function<void, true>::assertSecondArg(argument_types);
94	
95	    const DataTypePtr & argument_type = argument_types[0];
96	    WhichDataType which(argument_type);
97	
98	#define DISPATCH(TYPE) \
99	    if (which.idx == TypeIndex::TYPE) return std::make_shared<Function<TYPE, true>>(argument_types, params);
100	    FOR_BASIC_NUMERIC_TYPES(DISPATCH)
101	#undef DISPATCH
102	    if (which.idx == TypeIndex::Date) return std::make_shared<Function<DataTypeDate::FieldType, false>>(argument_types, params);
103	    if (which.idx == TypeIndex::DateTime) return std::make_shared<Function<DataTypeDateTime::FieldType, false>>(argument_types, params);
104	
105	    if constexpr (supportDecimal<Function>())
106	    {
107	        if (which.idx == TypeIndex::Decimal32) return std::make_shared<Function<Decimal32, false>>(argument_types, params);
108	        if (which.idx == TypeIndex::Decimal64) return std::make_shared<Function<Decimal64, false>>(argument_types, params);
109	        if (which.idx == TypeIndex::Decimal128) return std::make_shared<Function<Decimal128, false>>(argument_types, params);
110	        if (which.idx == TypeIndex::Decimal256) return std::make_shared<Function<Decimal256, false>>(argument_types, params);
111	        if (which.idx == TypeIndex::DateTime64) return std::make_shared<Function<DateTime64, false>>(argument_types, params);
112	    }
113	
114	    if constexpr (supportBigInt<Function>())
115	    {
116	        if (which.idx == TypeIndex::Int128) return std::make_shared<Function<Int128, true>>(argument_types, params);
117	        if (which.idx == TypeIndex::UInt128) return std::make_shared<Function<Int128, true>>(argument_types, params);
118	        if (which.idx == TypeIndex::Int256) return std::make_shared<Function<Int256, true>>(argument_types, params);
119	        if (which.idx == TypeIndex::UInt256) return std::make_shared<Function<UInt256, true>>(argument_types, params);
120	    }
121	
122	    throw Exception("Illegal type " + argument_type->getName() + " of argument for aggregate function " + name,
123	                    ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT);
124	}
125	
126	}
