5094	static void selectBestProjection(
5095	    const MergeTreeDataSelectExecutor & reader,
5096	    const StorageSnapshotPtr & storage_snapshot,
5097	    const SelectQueryInfo & query_info,
5098	    const Names & required_columns,
5099	    ProjectionCandidate & candidate,
5100	    ContextPtr query_context,
5101	    std::shared_ptr<PartitionIdToMaxBlock> max_added_blocks,
5102	    const Settings & settings,
5103	    const MergeTreeData::DataPartsVector & parts,
5104	    ProjectionCandidate *& selected_candidate,
5105	    size_t & min_sum_marks)
5106	{
5107	    MergeTreeData::DataPartsVector projection_parts;
5108	    MergeTreeData::DataPartsVector normal_parts;
5109	    for (const auto & part : parts)
5110	    {
5111	        const auto & projections = part->getProjectionParts();
5112	        auto it = projections.find(candidate.desc->name);
5113	        if (it != projections.end())
5114	            projection_parts.push_back(it->second);
5115	        else
5116	            normal_parts.push_back(part);
5117	    }
5118	
5119	    if (projection_parts.empty())
5120	        return;
5121	
5122	    auto projection_result_ptr = reader.estimateNumMarksToRead(
5123	        projection_parts,
5124	        candidate.required_columns,
5125	        storage_snapshot->metadata,
5126	        candidate.desc->metadata,
5127	        query_info,
5128	        query_context,
5129	        settings.max_threads,
5130	        max_added_blocks);
5131	
5132	    if (projection_result_ptr->error())
5133	        return;
5134	
5135	    auto sum_marks = projection_result_ptr->marks();
5136	    if (normal_parts.empty())
5137	    {
5138	        // All parts are projection parts which allows us to use in_order_optimization.
5139	        // TODO It might be better to use a complete projection even with more marks to read.
5140	        candidate.complete = true;
5141	    }
5142	    else
5143	    {
5144	        auto normal_result_ptr = reader.estimateNumMarksToRead(
5145	            normal_parts,
5146	            required_columns,
5147	            storage_snapshot->metadata,
5148	            storage_snapshot->metadata,
5149	            query_info, // TODO syntax_analysis_result set in index
5150	            query_context,
5151	            settings.max_threads,
5152	            max_added_blocks);
5153	
5154	        if (normal_result_ptr->error())
5155	            return;
5156	
5157	        if (normal_result_ptr->marks() == 0)
5158	            candidate.complete = true;
5159	        else
5160	        {
5161	            sum_marks += normal_result_ptr->marks();
5162	            candidate.merge_tree_normal_select_result_ptr = normal_result_ptr;
5163	        }
5164	    }
5165	    candidate.merge_tree_projection_select_result_ptr = projection_result_ptr;
5166	
5167	    // We choose the projection with least sum_marks to read.
5168	    if (sum_marks < min_sum_marks)
5169	    {
5170	        selected_candidate = &candidate;
5171	        min_sum_marks = sum_marks;
5172	    }
5173	}
