894	
895	    const auto & select = query_info.query->as<ASTSelectQuery &>();
896	
897	    size_t total_marks_pk = 0;
898	    size_t parts_before_pk = 0;
899	    try
900	    {
901	        MergeTreeDataSelectExecutor::filterPartsByPartition(
902	            parts,
903	            part_values,
904	            metadata_snapshot_base,
905	            data,
